//! tamias-driver-peregrin — the tamias content **driver** for
//! `peregrin-bundle`. tamias discovers this on `PATH` /
//! `<tamias-home>/drivers/` and runs
//! `<driver> <verb> --dir <d> --name <n> [--config <c>]`.
//!
//! Lifecycle verbs: `install` (no-op — the node config is generated by
//! `deploy`, which sees the stable store dir; `install` only sees the
//! evictable fetch-cache payload), `deploy` (regenerate the operator
//! node config from the manifest's `provider:` block), `uninstall`
//! (remove it). Service units are rendered by `tamias deploy` from
//! `provider.services[]` — the driver never writes them.
//!
//! Ops verbs (T8-5, reached via `tamias driver exec <pkg> <verb>`):
//!
//! - `hooks register|unregister [--dry-run] [--api-base <url>]
//!   [--token-env <NAME>]` — upsert/remove the forge webhooks the
//!   manifest's `provider.ingress[].hooks[]` declare. `--dry-run`
//!   prints the plan without touching the forge API or secrets.
//! - `health` — JSON probe: github-webhook `ping` against each ingress
//!   `listen`+`path`, else `systemctl --user is-active` per unit.
//! - `status` — JSON per-unit `is-active`/`is-enabled`.
//! - `logs [--lines N]` — `journalctl --user` over the provider units.
//! - `config-schema` — reserved verb: prints the JSON Schema
//!   (draft 2020-12) of the node config `deploy` writes, for
//!   `tamias driver config-schema <pkg>`.
//!
//! Thin wrapper over `peregrin_cli::provision`.

use std::path::PathBuf;
use std::process::ExitCode;

use clap::{Parser, Subcommand};
use peregrin_cli::{ops, provision};

#[derive(Parser)]
#[command(name = "tamias-driver-peregrin", version)]
struct Cli {
    #[command(subcommand)]
    cmd: Cmd,
}

#[derive(Subcommand)]
enum Cmd {
    /// No-op — node config materialization is `deploy`'s job (it sees
    /// the stable store dir; install only sees the fetch cache).
    Install {
        #[arg(long)]
        dir: PathBuf,
        #[arg(long)]
        name: String,
        #[arg(long)]
        config: Option<PathBuf>,
    },
    /// Regenerate the operator node config (provider.services units
    /// are rendered by `tamias deploy`, not this verb).
    Deploy {
        #[arg(long)]
        dir: PathBuf,
        #[arg(long)]
        name: String,
        #[arg(long)]
        config: Option<PathBuf>,
    },
    /// Remove the node config + host config + any legacy unit. `--dir`
    /// is accepted for dispatch parity (tamias always passes it) and
    /// ignored — uninstall resolves paths from `--name`.
    Uninstall {
        #[arg(long)]
        dir: PathBuf,
        #[arg(long)]
        name: String,
        #[arg(long)]
        config: Option<PathBuf>,
    },
    /// Manage the forge webhooks `provider.ingress[].hooks[]` declare —
    /// `tamias driver exec <pkg> hooks register|unregister`.
    Hooks {
        /// `register` upserts; `unregister` removes.
        action: HookAction,
        #[arg(long)]
        dir: PathBuf,
        #[arg(long)]
        name: String,
        #[arg(long)]
        config: Option<PathBuf>,
        /// Print the plan — no forge API calls, no secret resolution.
        #[arg(long)]
        dry_run: bool,
        /// Forge REST base (default `https://api.github.com`).
        #[arg(long)]
        api_base: Option<String>,
        /// Forge-token secret NAME (default `GITHUB_TOKEN`).
        #[arg(long)]
        token_env: Option<String>,
    },
    /// Probe the provider — JSON `{ok, probes[]}`: a github-webhook
    /// `ping` per ingress `listen`+`path`, else unit `is-active`.
    Health {
        #[arg(long)]
        dir: PathBuf,
        #[arg(long)]
        name: String,
        #[arg(long)]
        config: Option<PathBuf>,
    },
    /// Per-unit `systemctl --user is-active`/`is-enabled` — JSON.
    Status {
        #[arg(long)]
        dir: PathBuf,
        #[arg(long)]
        name: String,
        #[arg(long)]
        config: Option<PathBuf>,
    },
    /// `journalctl --user` over the provider's units.
    Logs {
        #[arg(long)]
        dir: PathBuf,
        #[arg(long)]
        name: String,
        #[arg(long)]
        config: Option<PathBuf>,
        /// Journal lines per unit.
        #[arg(long, default_value_t = 200)]
        lines: u32,
    },
    /// Print the JSON Schema (draft 2020-12) of the `--config` node
    /// config this driver generates — tamias's reserved `config-schema`
    /// verb. Instance-agnostic: the flags are accepted for dispatch
    /// parity and ignored.
    ConfigSchema {
        #[arg(long)]
        dir: PathBuf,
        #[arg(long)]
        name: String,
        #[arg(long)]
        config: Option<PathBuf>,
    },
    /// Report the content types + verbs this driver handles (JSON).
    Capabilities,
}

#[derive(clap::ValueEnum, Clone, Copy)]
enum HookAction {
    /// Upsert the manifest's forge hooks (idempotent — matches on the
    /// exact hook URL).
    Register,
    /// Remove the hooks the manifest declares.
    Unregister,
}

fn main() -> ExitCode {
    let cli = Cli::parse();
    let result = match cli.cmd {
        Cmd::Install { .. } => {
            println!("install: node config is generated by `tamias deploy` — nothing to do");
            return ExitCode::SUCCESS;
        }
        Cmd::Deploy { dir, name, config } => provision::deploy(&dir, &name, config.as_deref()),
        Cmd::Uninstall { name, config, .. } => provision::uninstall(&name, config.as_deref()),
        Cmd::Hooks {
            action,
            dir,
            name: _,
            config: _,
            dry_run,
            api_base,
            token_env,
        } => provision::hooks(
            &dir,
            &ops::OpsEnv::default(),
            matches!(action, HookAction::Register),
            dry_run,
            api_base.as_deref(),
            token_env.as_deref(),
        ),
        Cmd::Health { dir, name, .. } => provision::health(&dir, &name),
        Cmd::Status { dir, name, .. } => provision::status(&dir, &name),
        Cmd::Logs {
            dir, name, lines, ..
        } => provision::logs(&dir, &name, lines),
        Cmd::ConfigSchema { .. } => provision::config_schema(),
        Cmd::Capabilities => {
            println!(
                "{{\"types\":[\"peregrin-bundle\"],\"verbs\":[\"install\",\"deploy\",\"uninstall\",\"hooks\",\"health\",\"status\",\"logs\",\"config-schema\"]}}"
            );
            return ExitCode::SUCCESS;
        }
    };
    match result {
        Ok(output) => {
            println!("{output}");
            ExitCode::SUCCESS
        }
        Err(e) => {
            eprintln!("tamias-driver-peregrin: {e}");
            ExitCode::FAILURE
        }
    }
}
